using ll = long long;

int main() {
   ios_base::sync_with_stdio(false); cin.tie(nullptr);
   int N; ll K;
   cin >> N >> K;
   vector<vector<int>> adj(N);
   for (int i = 0; i < N - 1; ++i) {
      int v, u;
      cin >> v >> u;
      adj[--v].emplace_back(--u);
      adj[u].emplace_back(v);
   }
   vector<int> sz(N);
   function<void(int, int)> dfs1 = [&](int v, int p) {
      sz[v] = 1;
      for (int u : adj[v]) if (u != p) {
         dfs1(u, v);
         sz[v] += sz[u];
      }
   };
   dfs1(0, -1);
   int root = 0;
   for (int i = 1; i < N; ++i) {
      if (sz[i] >= N / 2 && sz[i] < sz[root]) root = i;
   }
   vector<int> dist(N);
   vector<int> top(N, -1);
   vector<int> par(N, -1);
   ll low = 0, high = 0;
   function<void(int, int, int)> dfs2 = [&](int v, int p, int r) {
      dist[v] = dist[p] + 1;
      top[v] = r;
      par[v] = p;
      {
         auto it = find(adj[v].begin(), adj[v].end(), p);
         assert(it != adj[v].end());
         adj[v].erase(it);
      }
      sz[v] = 1;
      for (int u : adj[v]) {
         dfs2(u, v, r);
         sz[v] += sz[u];
      }
      low += (sz[v] & 1);
      high += sz[v];
   };
   for (int v : adj[root]) {
      dfs2(v, root, v);
   }
   if (low > K || high < K || (high - K) % 2) {
      cout << "NO\n";
      return 0;
   }
   set<pair<int, int>> sizes;
   for (int v : adj[root]) {
      sizes.emplace(sz[v], v);
   }
   vector<set<pair<int, int>>> lcas(N);
   vector<int> deg(N);
   for (int v = 0; v < N; ++v) deg[v] = adj[v].size();
   for (int v = 0; v < N; ++v) if (v != root) {
      if (deg[v] == 0) {
      } else {
         lcas[top[v]].emplace(dist[v], v);
      }
   }
   vector<bool> matched(N);
   function<void(int)> kill = [&](int v) {
      assert(deg[v] == 0);
      if (--deg[par[v]] == 0) {
         v = par[v];
         lcas[top[v]].erase(pair<int, int>(dist[v], v));
      }
   };
   cout << "YES\n";
   while (high > K) {
      assert(sizes.size());
      int v = (--sizes.end())->second;
      sizes.erase(pair<int, int>(sz[v], v));
      assert(lcas[v].size());
      int mdist = (--lcas[v].end())->first;
      if (high - 2 * mdist <= K) {
         int x = lcas[v].lower_bound(pair<int, int>((high - K) / 2, -1))->second;
         int y = -1;
         for (int z : adj[x]) if (!matched[z]) {
            y = z;
            break;
         }
         high = K;
         cout << x + 1 << " " << y + 1 << "\n";
         matched[x] = true;
         matched[y] = true;
         break;
      } else {
         high -= 2 * mdist;
         assert(lcas[v].size());
         int u = (--lcas[v].end())->second;
         vector<int> nxts;
         while (nxts.size() < 2 && adj[u].size()) {
            int w = adj[u].back();
            adj[u].pop_back();
            if (!matched[w]) {
               nxts.emplace_back(w);
            }
         }
         if (nxts.size() < 2) nxts.emplace_back(u);
         assert(nxts.size() == 2);
         cout << nxts[0] + 1 << " " << nxts[1] + 1 << "\n";
         matched[nxts[0]] = true;
         matched[nxts[1]] = true;
         kill(nxts[0]);
         kill(nxts[1]);
         sz[v] -= 2;
         if (sz[v]) sizes.emplace(sz[v], v);
      }
   }
   vector<int> seq;
   function<void(int)> dfs3 = [&](int v) {
      if (!matched[v]) seq.emplace_back(v);
      for (int u : adj[v]) dfs3(u);
   };
   dfs3(root);
   int h = seq.size() / 2;
   for (int i = 0; i < h; ++i) {
      cout << seq[i] + 1 << " " << seq[i + h] + 1 << "\n";
   }
}
